import {build} from 'esbuild';import {cp,mkdir,writeFile} from 'node:fs/promises';import sharp from 'sharp';
await mkdir('desktop/bundle',{recursive:true});await cp('dist','desktop/bundle/dist',{recursive:true});await build({entryPoints:['worker.mjs'],outfile:'desktop/bundle/worker.mjs',bundle:true,format:'esm',platform:'node',target:'node22'});
const png=await sharp('assets/icon.svg').resize(256,256).png().toBuffer();const head=Buffer.alloc(22);head.writeUInt16LE(1,2);head.writeUInt16LE(1,4);head.writeUInt16LE(1,10);head.writeUInt16LE(32,12);head.writeUInt32LE(png.length,14);head.writeUInt32LE(22,18);await writeFile('desktop/bundle/icon.ico',Buffer.concat([head,png]));
